import requests
import csv

# 初期設定
PX, PY = 1, 1  # プレイヤーの初期座標
W = 40  # タイルの幅
maze = []
maze_url = "https://n3s.nadesi.com/image.php?f=19.csv"

# データを読み込む
response = requests.get(maze_url)
reader = csv.reader(response.text.splitlines())
for row in reader:
    maze.append([int(x) for x in row])

def draw_tile(x, y, v):
    if v == 0:
        color = "white"
    elif v == 1:
        color = "brown"
    else:
        color = "gray"
    print(f"[X{x*W},Y{y*W},W{W},W{W}]に四角描画。")

def draw_maze():
    for y in range(8):
        for x in range(40):
            v = maze[y][x]
            draw_tile(x, y, v)
    # プレイヤーの描画
    print("青色に塗色設定。")
    print("30の描画フォント設定。")
    print("[PX×W+5,PY×W+30]に「♪」の文字描画。")

def main():
    global PX, PY
    draw_maze()

    while True:
        key = input("キーを押してください：")
        x, y = PX, PY  # 仮の移動座標

        if key == "ArrowUp":
            y -= 1
        elif key == "ArrowDown":
            y += 1
        elif key == "ArrowLeft":
            x -= 1
        elif key == "ArrowRight":
            x += 1

        # 壁を突き破らないよう座標をチェック
        if x < 0 or y < 0:
            continue
        if x >= 40 or y >= 8:
            continue
        # 移動先が壁なら進めない
        if maze[y][x] == 1:
            continue

        PX, PY = x, y  # 正式にプレイヤーを移動
        draw_maze()

        # クリア判定
        if PX == 10 and PY == 6:
            print("ゲームクリア")
            PX, PY = 1, 1
            break

if __name__ == "__main__":
    main()

# 初期設定 --- (*1)
PX = 1
PY = 1  # プレイヤーの初期座標
W = 10  # タイルの幅
SZ = 55  # 迷路のサイズ
迷路URL = "https://n3s.nadesi.com/image.php?f=20.csv"
宝 = 0
迷路 = []

# データを読み込む --- (*2)
import requests
import csv

response = requests.get(迷路URL)
csv_data = response.text.splitlines()
reader = csv.reader(csv_data)
for row in reader:
    int_row = [int(item) for item in row]
    迷路.append(int_row)

# 迷路描画処理 --- (*3)
def 迷路描画処理():
    for Y in range(SZ):
        for X in range(SZ):
            V = 迷路[Y][X]
            タイル描画(X, Y, V)

# (XとYにVの)タイル描画 --- (*5)
def タイル描画(X, Y, V):
    if V == 0:
        print(f"[{X * W}, {Y * W}, {W}, {W}]に白色に塗色設定。")
    elif V == 1:
        print(f"[{X * W}, {Y * W}, {W}, {W}]に茶色に塗色設定。")
    elif V == 2:
        print(f"[{X * W}, {Y * W}, {W}, {W}]に黄色に塗色設定。")
    elif V == 3:
        print(f"[{X * W}, {Y * W}, {W}, {W}]に黄色に塗色設定。")
    elif V == 4:
        print(f"[{X * W}, {Y * W}, {W}, {W}]に黄色に塗色設定。")

# キーボードイベントを設定 --- (*6)
import keyboard

while True:
    event = keyboard.read_event()
    if event.event_type == 'down':
        X = PX
        Y = PY  # 仮の移動座標
        if event.name == 'up':
            Y -= 1
        elif event.name == 'down':
            Y += 1
        elif event.name == 'left':
            X -= 1
        elif event.name == 'right':
            X += 1

        if (X != PX) or (Y != PY):
            迷路描画処理()

        # 壁を突き破らないよう座標をチェック --- (*7)
        if (X < 0) or (Y < 0):
            continue
        if (X >= SZ) or (Y >= SZ):
            continue

        # 移動先が壁なら進めない --- (*8)
        M = 迷路[Y][X]
        if M == 1:
            continue

        PX = X
        PY = Y  # 正式にプレイヤーを移動 --- (*9)

        if M == 2:
            print("罠に捕まった！スタートに地点に戻ってしまった")
            PX = 1
            PY = 1
            迷路[Y][X] = 0  # 罠は一度だけ発動
        elif M == 3:
            print("宝を見つけた！")
            宝 += 1
            迷路[Y][X] = 0  # 通路に戻す
        elif M == 4:
            if 宝 == 0:
                print("出口を見つけたが、せっかくなら宝を持って帰りたい")
            else:
                print(f"宝を{宝}個持ってゴール！ゲームクリア")
        迷路描画処理()

